INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('dw1iqmvj6srtaris8dw1ijm6vlj9hxp2', '2026-Q2', 'Jun–Jul/2026 (T2)', '2026-06-19T10:56'::timestamptz, 'Tchiêlo Lisboa Camboim', 'tchielo lisboa camboim', 'PHARUS', 'Rodrigo Amorim', 7.0, 'Neutro', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'Ainda não obtive os resultados, então não tenho 100% de segurança para indicar.', 'Segundo os meus critérios para indicar algo a alguém, não há o que fazer. o processo é lento mesmo. Mas darei nota 10 assim que vir o plano se concretizando.', NULL, 'Uma lista de fatores: Ver que o plano está dando certo, clareza e boas condições para renovação, ver que o dinheiro investido na quarta via se pagou antes da renovação.', 'Já comentei isso com o Rodrigo, me preocupa o fato de a venda do serviço ser anual enquanto o projeto é de longo prazo (cerca de 7 anos). Iniciar o planejamento sem a certeza da continuidade gera uma insegurança natural. Como o valor do investimento é alto, fica difícil prever minha permanência daqui a um ano. Na minha visão, o modelo ideal seria o de mensalidade (recorrência). Isso permitiria que o cliente ficasse pelo tempo que fizesse sentido para ele, eliminando a barreira e a burocracia de ter que renovar o plano para não interromper o processo.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'dw1iqmvj6srtaris8dw1ijm6vlj9hxp2', 'base mecanismos (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo,