INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('mvesodflypjmbgdnmvesos1odu7mintn', '2026-Q2', 'Jun–Jul/2026 (T2)', '2026-06-22T10:40'::timestamptz, 'Sergio Luis Santoni de Lima', 'sergio luis santoni de lima', 'PHARUS', 'Rodrigo Amorim', 1.0, 'Detrator', 8.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Tenho clareza e estou executando com consistência', 'Esperava mais dinamismo, tenho capital para investir, mas não há no momento imóveis em leilão ou na planta para investir. Até agora apenas consórcio. TALVEZ daqui 2 meses, mas pode ser que demore mais, não se tem certeza. Até agora apenas consórcio (8 cotas).Enquanto isso, pago 2 mil reais por mês e num piscar de olhos já terei que renovar o contrato e serão mais 20 mil. No momento minha avaliação é muito ruim, espero que mude.', 'Estendam o período do meu contrato, pois tenho capital para investir, mas nenhuma opção de alocação está e, pelo que foi dito, nem estará nos próximos meses a minha disposição. Estou pagando 2 mil por mês, meu contrato está passando.', NULL, 'O que eu quero é continuar sim, quero atingir a promessa de 30 mil por mês feita pelo Adrian,  mas me parece tudo muito lento. O que me faria continuar é por os motores de construção de patrimônio em prática.', '.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'mvesodflypjmbgdnmvesos1odu7mintn', 'cadastro 2026-T2 (22 dias)', 'cadastro 2026-T2') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente